from pathlib import Path

# Look in session directory for task data
session_dir = Path('/home/USER/runs/paper/qwen-in-glm-h-u1/frozen/seen-6/play')

print(f"Session dir: {session_dir}")
print(f"Exists: {session_dir.exists()}")

for root, dirs, files in Path(session_dir).rglob('*'):
    if files:
        print(f"\n{root}:")
        for f in sorted(files):
            p = root / f
            try:
                with open(p) as fp:
                    try:
                        content = json.load(fp)
                        if isinstance(content, dict):
                            print(f"  {f}: dict with keys={list(content.keys())[:3]}, task={content.get('task', 'N/A')}")
                    except:
                        try:
                            print(f"  {f}: {len(json.dumps(content)) if content else 0} bytes")
                        except:
                            print(f"  {f}: non-JSON")
            except:
                print(f"  {f}: non-JSON ({p.stat().st_size} bytes)")
